content.text:
{
  "theme": "default",
  "style": "minimal",
  "layouts": [
    {
      "name": "title",
      "description": "Clean black title slide with white text",
      "className": "min-title",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Main heading text",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "content",
          "type": "string",
          "description": "Content like author info (markdown supported, keep concise)",
          "required": false,
          "maxLength": 500
        },
        {
          "name": "backgroundImage",
          "type": "string",
          "description": "Optional background image path or URL",
          "required": false
        }
      ]
    },
    {
      "name": "section",
      "description": "Simple black section divider slide",
      "className": "min-section",
      "params": [
        {
          "name": "title",
          "type": "string",
          "description": "Section title",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "subtitle",
          "type": "string",
          "description": "Subtitle or description",
          "required": false,
          "maxLength": 200
        }
      ]
    },
    {
      "name": "list",
      "description": "Simple bullet list slide",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 54
        },
        {
          "name": "list",
          "type": "array",
          "description": "List items (max 10 items)",
          "required": true,
          "maxItems": 10,
          "maxLength": 70
        },
        {
          "name": "citations",
          "type": "string",
          "description": "Citation (no line break)",
          "required": false,
          "maxLength": 130
        }
      ]
    },
    {
      "name": "table",
      "description": "Minimal table with black header and clean borders",
      "className": "min-table",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 54
        },
        {
          "name": "tableMarkdown",
          "type": "string",
          "description": "Table in markdown format (max 5 rows)",
          "required": true
        },
        {
          "name": "description",
          "type": "string",
          "description": "Table description below table (no line break)",
          "required": false,
          "maxLength": 75
        },
        {
          "name": "citations",
          "type": "string",
          "description": "Citation (no line break)",
          "required": false,
          "maxLength": 130
        }
      ]
    },
    {
      "name": "image-right",
      "description": "Text on left, image on right (60:40 split), clean design",
      "className": "min-img-right",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "list",
          "type": "array",
          "description": "List items for the content side",
          "required": true,
          "maxItems": 10
        },
        {
          "name": "imagePath",
          "type": "string",
          "description": "Image file path or URL",
          "required": true
        },
        {
          "name": "citations",
          "type": "string",
          "description": "Citation (no line break)",
          "required": false,
          "maxLength": 130
        }
      ]
    },
    {
      "name": "image-center",
      "description": "Centered image slide, clean and minimal",
      "className": "min-img-center",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 54
        },
        {
          "name": "imagePath",
          "type": "string",
          "description": "Image file path or URL",
          "required": true
        },
        {
          "name": "description",
          "type": "string",
          "description": "Image description below image",
          "required": false,
          "maxLength": 75
        },
        {
          "name": "caption",
          "type": "string",
          "description": "Image caption displayed below",
          "required": false,
          "maxLength": 120
        },
        {
          "name": "citations",
          "type": "string",
          "description": "Citation (no line break)",
          "required": false,
          "maxLength": 130
        }
      ]
    },
    {
      "name": "content",
      "description": "Pure markdown content slide",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 54
        },
        {
          "name": "body",
          "type": "string",
          "description": "Free-form markdown body",
          "required": true
        }
      ]
    },
    {
      "name": "quote",
      "description": "Quote slide with left border accent, no extra decoration",
      "className": "min-quote",
      "params": [
        {
          "name": "quote",
          "type": "string",
          "description": "The quote text",
          "required": true
        },
        {
          "name": "attribution",
          "type": "string",
          "description": "Quote attribution (e.g. author name)",
          "required": false,
          "maxLength": 80
        },
        {
          "name": "content",
          "type": "string",
          "description": "Additional content below the quote",
          "required": false
        }
      ]
    },
    {
      "name": "two-column",
      "description": "Two-column layout with a thin divider line",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "leftTitle",
          "type": "string",
          "description": "Left column title",
          "required": false,
          "maxLength": 60
        },
        {
          "name": "leftList",
          "type": "array",
          "description": "Left column list items",
          "required": false,
          "maxItems": 8
        },
        {
          "name": "rightTitle",
          "type": "string",
          "description": "Right column title",
          "required": false,
          "maxLength": 60
        },
        {
          "name": "rightList",
          "type": "array",
          "description": "Right column list items",
          "required": false,
          "maxItems": 8
        }
      ]
    },
    {
      "name": "big-statement",
      "description": "Large impactful statement slide with bold centered text",
      "className": "min-statement",
      "params": [
        {
          "name": "statement",
          "type": "string",
          "description": "The main statement or headline",
          "required": true,
          "maxLength": 120
        },
        {
          "name": "subtitle",
          "type": "string",
          "description": "Optional supporting text below the statement",
          "required": false,
          "maxLength": 200
        }
      ]
    },
    {
      "name": "statistics",
      "description": "Minimal statistics display with black numbers and thin underline (use 'Number|Label' format)",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "stats",
          "type": "array",
          "description": "Statistics in 'Number|Label' format",
          "required": true,
          "maxItems": 5
        },
        {
          "name": "caption",
          "type": "string",
          "description": "Optional caption below statistics",
          "required": false,
          "maxLength": 200
        }
      ]
    },
    {
      "name": "highlight-box",
      "description": "Minimal message box for key takeaways",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Box heading",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "content",
          "type": "string",
          "description": "Box content text",
          "required": false,
          "maxLength": 500
        }
      ]
    },
    {
      "name": "pull-quote",
      "description": "Minimal decorative impact quote with large quotation marks",
      "className": "min-pull-quote",
      "params": [
        {
          "name": "quote",
          "type": "string",
          "description": "The quote text (short, impactful)",
          "required": true,
          "maxLength": 200
        },
        {
          "name": "attribution",
          "type": "string",
          "description": "Quote attribution",
          "required": false,
          "maxLength": 80
        },
        {
          "name": "context",
          "type": "string",
          "description": "Additional context or source",
          "required": false,
          "maxLength": 120
        }
      ]
    },
    {
      "name": "agenda",
      "description": "Clean agenda slide with numbered items and optional time durations (use 'Item name|Duration' format)",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading (max 80 chars, ~48 chars for Japanese)",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "items",
          "type": "array",
          "description": "Agenda items in 'Item name|Duration' format (duration is optional). Max 8 items.",
          "required": true,
          "maxItems": 8
        },
        {
          "name": "subtitle",
          "type": "string",
          "description": "Optional subtitle displayed below the heading",
          "required": false,
          "maxLength": 120
        }
      ]
    },
    {
      "name": "comparison",
      "description": "Side-by-side comparison with explicit left/right titles and list items, separated by a thin divider",
      "params": [
        {
          "name": "heading",
          "type": "string",
          "description": "Slide heading (max 80 chars, ~48 chars for Japanese)",
          "required": true,
          "maxLength": 80
        },
        {
          "name": "leftTitle",
          "type": "string",
          "description": "Left panel title (e.g., 'Before', 'Option A', 'Pros')",
          "required": true,
          "maxLength": 50
        },
        {
          "name": "leftList",
          "type": "array",
          "description": "Left panel list items. Max 6 items.",
          "required": true,
          "maxItems": 6
        },
        {
          "name": "rightTitle",
          "type": "string",
          "description": "Right panel title (e.g., 'After', 'Option B', 'Cons')",
          "required": true,
          "maxLength": 50
        },
        {
          "name": "rightList",
          "type": "array",
          "description": "Right panel list items. Max 6 items.",
          "required": true,
          "maxItems": 6
        }
      ]
    }
  ]
}
